python
def tallerKeycapsBossReceipt(readings, k):
    a=readings
    out=[]
    out=[0]*len(a)
    stack=[]
    for i,x in enumerate(a):
        while stack and a[stack[-1]]<x:
            j=stack.pop()
            out[j]=i-j
        stack.append(i)
    return sum((i+1)*x for i,x in enumerate(out))


